const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const meta = (p.fields && typeof p.fields === 'object') ? p.fields : {};

const severity = String(p.severity || 'unknown').toLowerCase();
const COLOR = { error: 15158332, warning: 15105570 };
const show = v => (v !== null && typeof v === 'object') ? JSON.stringify(v) : String(v);

// Discord allows 25 fields, 1024 chars each. Everything past hostname/type is
// whatever the event happened to carry, so new PVE metadata appears on its own.
const fields = [
    { name: 'Node', value: show(meta.hostname || 'n/a').slice(0, 1024), inline: true },
    { name: 'Event', value: show(meta.type || 'n/a').slice(0, 1024), inline: true },
    { name: 'Severity', value: severity, inline: true }
];
let fieldChars = fields.reduce((a, f) => a + f.name.length + f.value.length, 0);
for (const [k, v] of Object.entries(meta)) {
    if (k === 'hostname' || k === 'type' || fields.length >= 25) continue;
    const name = k.slice(0, 256);
    const value = show(v).slice(0, 1024) || '—';
    // Metadata must not crowd out the message it describes.
    if (fieldChars + name.length + value.length > 2400) continue;
    fields.push({ name: name, value: value, inline: true });
    fieldChars += name.length + value.length;
}

const title = String(p.title || 'Proxmox notification').slice(0, 256);

// Whole embed must stay under 6000; give the description whatever is left,
// capped by Discord's own 4096 limit on that one attribute.
let body = String(p.message == null ? '' : p.message).replace(/```/g, "'''");
const LIMIT = Math.max(0, Math.min(3900, 5800 - title.length - fieldChars - 60));
if (LIMIT < 120) {
    body = '';
} else if (body.length > LIMIT) {
    const head = Math.floor(LIMIT * 0.55);
    const tail = LIMIT - head;
    body = body.slice(0, head) + "\n\n... " + (body.length - head - tail) + " characters truncated ...\n\n" +
        (tail > 0 ? body.slice(body.length - tail) : '');
}

const ts = Number(p.timestamp);

const embed = {
    title: title,
    color: COLOR[severity] || 9807270,
    description: body.length ? "```\n" + body + "\n```" : "_(no message body)_",
    fields: fields,
    timestamp: new Date((Number.isFinite(ts) && ts > 0 ? ts * 1000 : Date.now())).toISOString()
};

const url = env.get('DISCORD_WEBHOOK_URL');
if (!url) {
    node.error('DISCORD_WEBHOOK_URL is not set', msg);
    return null;
}

msg.method = 'POST';
msg.url = url;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { username: 'Proxmox', embeds: [embed] };
return msg;

// http request does not throw on non-2xx, so surface it here.
const sc = msg.statusCode;
if (typeof sc !== 'number' || sc < 200 || sc >= 300) {
    let detail = msg.payload;
    try { detail = typeof detail === 'string' ? detail : JSON.stringify(detail); }
    catch (e) { detail = String(detail); }
    node.warn('Discord returned HTTP ' + sc + ': ' + String(detail).slice(0, 300));
}
return msg;
